import org.junit.Test
import org.junit.Assert.*

class ConflictPolicyTest {

    @Test
    fun `clinical fields use vector_clock not LWW`() {
        val clinicalFields = listOf(
            "patient_case_status",
            "vet_note_summary",
            "triage_report_body",
            "risk_level",
            "suspected_condition"
        )
        val policyMatrix = mapOf(
            "patient_case_status" to ConflictPolicy.vector_clock,
            "vet_note_summary" to ConflictPolicy.vector_clock,
            "triage_report_body" to ConflictPolicy.vector_clock,
            "risk_level" to ConflictPolicy.vector_clock,
            "suspected_condition" to ConflictPolicy.vector_clock
        )
        for (field in clinicalFields) {
            assertEquals("Field $field must use vector_clock",
                ConflictPolicy.vector_clock, policyMatrix[field])
        }
    }

    @Test
    fun `metadata fields can use LWW`() {
        val metadataFields = listOf(
            "last_viewed_screen",
            "local_cache_timestamp"
        )
        val policyMatrix = mapOf(
            "last_viewed_screen" to ConflictPolicy.last_writer_wins,
            "local_cache_timestamp" to ConflictPolicy.last_writer_wins
        )
        for (field in metadataFields) {
            assertEquals("Field $field should use last_writer_wins",
                ConflictPolicy.last_writer_wins, policyMatrix[field])
        }
    }

    @Test(expected = IllegalStateException::class)
    fun `forbidden transition conflicted to queued_for_sync is rejected`() {
        val stateMachine = PendingReportStateMachine()
        stateMachine.transition(PendingReportState.conflicted, PendingReportState.queued_for_sync)
    }
}

class PendingReportStateMachine {
    private val forbiddenTransitions = setOf(
        PendingReportState.conflicted to PendingReportState.queued_for_sync,
        PendingReportState.failed_terminal to PendingReportState.syncing,
        PendingReportState.requires_review to PendingReportState.queued_for_sync,
        PendingReportState.merged to PendingReportState.draft,
        PendingReportState.merged to PendingReportState.queued_for_sync
    )

    fun transition(from: PendingReportState, to: PendingReportState) {
        if (forbiddenTransitions.contains(from to to)) {
            throw IllegalStateException("Transition $from -> $to is forbidden")
        }
    }
}
